ScriptPromise<IDLString> Clipboard::readText(
    ScriptState* script_state,
    ExceptionState& exception_state) {
  return ClipboardPromise::CreateForReadText(
      GetExecutionContext(), script_state, exception_state);
}

ScriptPromise<IDLString> ClipboardPromise::CreateForReadText(
    ExecutionContext* context,
    ScriptState* script_state,
    ExceptionState& exception_state) {
  auto* resolver = MakeGarbageCollected<ScriptPromiseResolver<IDLString>>(...);
  ClipboardPromise* clipboard_promise =
      MakeGarbageCollected<ClipboardPromise>(context, resolver, exception_state);
  clipboard_promise->HandleReadText();
  return resolver->Promise();
}

void ClipboardPromise::HandleReadTextWithPermission(
    mojom::blink::PermissionStatus status) {
  if (status != mojom::blink::PermissionStatus::GRANTED) {
    script_promise_resolver_->RejectWithDOMException(
        DOMExceptionCode::kNotAllowedError, "Read permission denied.");
    return;
  }
  // ... proceed with read
}

String SystemClipboard::ReadPlainText(
    mojom::blink::ClipboardBuffer buffer) {
  if (!IsValidBufferType(buffer) || !clipboard_.is_bound())
    return String();
  if (snapshot_ && snapshot_->HasPlainText(buffer)) {
    return snapshot_->PlainText(buffer);
  }
  String text;
  clipboard_->ReadText(buffer, &text);  // SYNC MOJO CALL
  return text;
}

