virtual void ReadText(ClipboardBuffer buffer,
                      std::optional<DataTransferEndpoint> data_dst,
                      ReadTextCallback callback) const = 0;

// Dispatches to platform-specific implementation

void ClipboardHostImpl::OnReadText(
    ui::ClipboardBuffer clipboard_buffer,
    ReadTextCallback callback,
    std::u16string text) {
  ClipboardPasteData clipboard_paste_data;
  clipboard_paste_data.text = std::move(text);
  PasteIfPolicyAllowed(clipboard_buffer, ..., std::move(clipboard_paste_data), ...);
}

base::BindOnce(
